-- =============================================================================
-- 3. WATCHERS (non-task objects; tasks use core.task_watchers)
-- =============================================================================
-- PROVEN: followers exist on threads and pages (users and groups). ASSUMED: one generic table, groups expanded app-side.
CREATE TABLE watchers (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  object_type text NOT NULL CHECK (object_type IN ('comment','doc','page','list','folder','space','goal')),
  object_id uuid NOT NULL,
  user_id uuid NOT NULL /* id -> identity.users */,
  reason text NOT NULL DEFAULT 'manual' CHECK (reason IN ('creator','owner','commenter','mentioned','manual')),  -- ASSUMED rule
  muted boolean NOT NULL DEFAULT false,              -- PROVEN thread_unfollower_ids
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, object_type, object_id, user_id)   -- fan-out: all watchers of one object
);

CREATE INDEX watchers_user ON watchers (workspace_id, user_id, object_type);

