-- notifications: PROVEN fields type, object, actor, created/read/cleared/snoozed (tabs Primary, Other, Later, Cleared).
-- ASSUMED: one row per recipient per event, is_important snapshot, hash partitioning (hot reads are per user).
-- PARTITION BY HASH (workspace_id) x 16.
CREATE TABLE notifications (
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  id            uuid NOT NULL,
  user_id       uuid NOT NULL /* id -> identity.users */,   -- recipient
  type          text NOT NULL REFERENCES notification_types(key),
  event_id      uuid NOT NULL,                       -- change_log.id that produced it (no FK: the log is purged earlier)
  object_type   text NOT NULL,
  object_id     uuid NOT NULL,                       -- bundle key together with object_type
  actor_id      uuid /* id -> identity.users */,
  is_important  boolean NOT NULL DEFAULT false,      -- snapshot of the recipient's importance at fan-out -> Primary tab
  payload       jsonb NOT NULL DEFAULT '{}',         -- render snippet (title, excerpt); never filtered
  read_at       timestamptz,
  cleared_at    timestamptz,
  snoozed_until timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, id),
  UNIQUE (workspace_id, event_id, user_id, type)     -- fan-out is idempotent on replay
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('notifications', 16);

-- 'unread inbox for user', Primary (is_important) / Other tabs, newest first.
CREATE INDEX notifications_inbox ON notifications (workspace_id, user_id, is_important, created_at DESC)
  WHERE cleared_at IS NULL AND snoozed_until IS NULL;

-- unread badge count.
CREATE INDEX notifications_unread ON notifications (workspace_id, user_id, created_at DESC)
  WHERE read_at IS NULL AND cleared_at IS NULL;

-- bundle rows ('3 unread on task X') and 'mark all on this object read'.
CREATE INDEX notifications_bundle ON notifications (workspace_id, user_id, object_type, object_id, created_at DESC);

-- Later tab + the snooze waker.
CREATE INDEX notifications_snoozed ON notifications (workspace_id, user_id, snoozed_until) WHERE snoozed_until IS NOT NULL AND cleared_at IS NULL;

-- Cleared tab.
CREATE INDEX notifications_cleared ON notifications (workspace_id, user_id, cleared_at DESC) WHERE cleared_at IS NOT NULL;

-- preferences: PROVEN 'Customize importance' per type. Channel flags ASSUMED. NULL = catalog default.
CREATE TABLE notification_preferences (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  type text NOT NULL REFERENCES notification_types(key),
  important boolean,
  in_app boolean NOT NULL DEFAULT true,
  email boolean,
  push boolean,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, user_id, type)          -- fan-out loads prefs of N recipients with one IN query
);

CREATE TABLE notification_settings (                 -- do-not-disturb, digest, quiet hours: settings JSONB (PROVEN screens exist)
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  settings jsonb NOT NULL DEFAULT '{}',
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (workspace_id, user_id)
);

-- delivery attempts per channel (PROVEN: pushNotifications/log browser|mobile; email ASSUMED).
CREATE TABLE notification_deliveries (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  notification_id uuid NOT NULL,
  user_id uuid NOT NULL /* id -> identity.users */,
  channel text NOT NULL CHECK (channel IN ('browser','mobile','email')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','skipped_read','failed')),
  send_after timestamptz NOT NULL DEFAULT now(),     -- ASSUMED delay so already-read notifications are skipped
  attempts smallint NOT NULL DEFAULT 0,
  last_error text,
  sent_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (workspace_id, notification_id) REFERENCES notifications(workspace_id, id) ON DELETE CASCADE
);

-- delivery worker: due pending deliveries (global scan by design).
CREATE INDEX notification_deliveries_due ON notification_deliveries (send_after) WHERE status = 'pending';

CREATE INDEX notification_deliveries_notif ON notification_deliveries (workspace_id, notification_id);

ALTER TABLE notification_types ADD COLUMN is_mandatory boolean NOT NULL DEFAULT false;
